head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[content > P > frameMode]<br/>Content 영역이 구성되는 Frame 의 종류를 설정합니다.",
    "validation" : [        
        "미설정 시 src 속성으로 WebSquare XML 페이지를 연결한 경우 'wframe' 으로 적용됩니다.",
        "iframe 설정 시 Content 영역이 iFrame 으로 구성됩니다.",        
        "wframe 설정 시 Content 영역이 wFrame 으로 구성됩니다.",
        "wframePreload 설정 시 Content 영역는 wFrame 으로 구성됩니다.",
        "pageFrame 설정 시 Content 영역는 pageFrame 으로 구성됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정   
    let properties = {
        frameMode: con_frameMode.getText(),
    };

    let cList = $c.gcm.createCList(properties);          

    let grp_comp = $c.gcm.getTestGroup();    
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:tabControl ' + strNameSpace + ' alwaysDraw="false" id="" style="width:500px;height:200px;">';
    strTarget += '<w2:tabs disabled="false" style="height:40px;" id="tabs1" label="Tabs1"></w2:tabs>';
    strTarget += '<w2:tabs disabled="false" style="height:40px" id="tabs2" label="Tabs2"></w2:tabs>';    
    strTarget += '<w2:content ' + cList + ' src="/sample/common_link/tabControl_link_1.xml" style="height:160px;" id="content1">';    
    strTarget += '</w2:content>';
    strTarget += '<w2:content ' + cList + ' src="/sample/common_link/tabControl_link_2.xml" style="height:160px" id="content2">';    
    strTarget += '</w2:content>';    
    strTarget += '</w2:tabControl>';

    // target 생성
    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "tabControl",
        strTarget,
        grp_comp
    );

    scwin.btn_getFrameMode_onclick();
}



scwin.btn_getFrameMode_onclick = function (e) {
    setTimeout(() => {           
        let contentBody1 = document.querySelector('[id*=target1_contents_content1_body]');    

        if (contentBody1) {
            wf_body_bottom.getObj("scwin").setReturnValue("content1 의 tagName : " + contentBody1.tagName);
            wf_body_bottom.getObj("scwin").setReturnValue("content1 의 className : " + contentBody1.className);
        }            
    }, 100);
};
